(()=>{
const prior=showConfig;showConfig=function(type,origin){if(type==='organograma')return showOrganogram(origin);return prior(type,origin)};
function showOrganogram(origin='Gestão de Pessoas'){
 const view=document.getElementById('sector-view'),box=document.getElementById('sector-content');view.classList.remove('financial-groups','financial-hierarchy','account-orange');view.style.setProperty('--menu-accent','#7c3aed');view.querySelector('.panel').style.setProperty('--panel-color','#7c3aed');view.querySelector('.panel').style.setProperty('--panel-text','#5520ad');view.querySelectorAll('.view-alphabetize,.financial-expand-all,.location-tool').forEach(e=>e.remove());document.getElementById('sector-title').textContent='Organograma';document.getElementById('sector-path').textContent='Gestão de Pessoas / Organograma';document.getElementById('crumb').textContent='Gestão de Pessoas / Organograma';setSectorBack(()=>openSection(sections[6][0],'Gestão de Pessoas','people-settings','#7c3aed'));box.replaceChildren();
 let tree=[];try{const saved=JSON.parse(localStorage.getItem('cicluz-location-tree-v1')||'[]');tree=Array.isArray(saved)?saved:saved.tree||[]}catch{}
 const toolbar=document.createElement('div');toolbar.className='organogram-toolbar';const btn=(text,fn)=>{const b=document.createElement('button');b.type='button';b.className='btn secondary';b.textContent=text;b.onclick=fn;return b};toolbar.append(btn('Editar estrutura',()=>showConfig('area',origin)),btn('Atualizar',()=>showOrganogram(origin)));box.append(toolbar);const description=document.createElement('p');description.className='organogram-note';description.textContent='Estrutura por áreas, setores, locais e sublocais. Os vínculos de liderança ainda não foram definidos.';box.append(description);
 if(!tree.length){const empty=document.createElement('div');empty.className='organogram-empty';const h=document.createElement('h3');h.textContent='Comece pela estrutura da empresa';const p=document.createElement('p');p.textContent='Cadastre as áreas e os níveis abaixo delas para visualizar o organograma.';empty.append(h,p,btn('+ Cadastrar área',()=>showConfig('area',origin)));box.append(empty);return}
 const canvas=document.createElement('div');canvas.className='organogram-canvas';canvas.setAttribute('aria-label','Organograma da estrutura da empresa');const root=document.createElement('div');root.className='organogram-company';root.textContent='Estrutura da empresa';canvas.append(root);const list=document.createElement('ul');list.className='organogram-branches';const levels=['Área','Setor','Local','Sublocal'];
 function draw(nodes,target,level){for(const n of nodes){const li=document.createElement('li');const card=document.createElement('div');card.className='organogram-card';const badge=document.createElement('span');badge.className='organogram-badge';badge.style.background=n.color||'#7c3aed';badge.textContent=n.sigla||Array.from(n.name).slice(0,3).join('');const copy=document.createElement('span');const type=document.createElement('small');type.textContent=levels[level]||'Unidade';const title=document.createElement('b');title.textContent=n.name;copy.append(type,title);card.append(badge,copy);li.append(card);if(n.children?.length){const details=document.createElement('details');details.open=true;const summary=document.createElement('summary');const count=(node)=>(node.children||[]).reduce((a,c)=>a+1+count(c),0);summary.textContent=count(n)+(count(n)===1?' item':' itens');const children=document.createElement('ul');draw(n.children,children,level+1);details.append(summary,children);li.append(details)}target.append(li)}}draw(tree,list,0);canvas.append(list);box.append(canvas);toolbar.append(btn('Expandir tudo',()=>canvas.querySelectorAll('details').forEach(d=>d.open=true)),btn('Recolher tudo',()=>canvas.querySelectorAll('details').forEach(d=>d.open=false)))
}
})();
